use tauri_build::{AppManifest, Attributes};

// Every command the webview may call is declared here, so Tauri applies an
// ACL to it and the capability must allow it by name. An undeclared app
// command would be open to every window. Work declares the offline store's
// two commands and the four sign in commands (the webview never reaches the
// custody slot itself): no keychain command, no probe scaffolding.
//
// The `shell-proof` feature adds one command, `proof_report`, and its own
// capability folder (capabilities-proof/). tauri-build writes
// permissions/autogenerated/*.toml for these names and never deletes a stale
// one, and it reads every file there. So the file for the proof command is not
// committed (it is git ignored and appears only when a proof build generates
// it), and `drop_stale_permissions` removes any file whose command is not in
// this build's list before tauri-build reads the folder, so a default build
// never carries the proof command in its ACL manifest.
#[cfg(feature = "shell-proof")]
const COMMANDS: &[&str] = &[
    "proof_report",
    "run_statement",
    "run_atomic",
    "auth_sign_in",
    "auth_resume",
    "auth_exchange",
    "auth_sign_out",
];
#[cfg(not(feature = "shell-proof"))]
const COMMANDS: &[&str] = &[
    "run_statement",
    "run_atomic",
    "auth_sign_in",
    "auth_resume",
    "auth_exchange",
    "auth_sign_out",
];

fn drop_stale_permissions() {
    let Ok(entries) = std::fs::read_dir("permissions/autogenerated") else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let stem = path.file_stem().and_then(|s| s.to_str()).unwrap_or("");
        if path.extension().is_some_and(|e| e == "toml") && !COMMANDS.contains(&stem) {
            let _ = std::fs::remove_file(&path);
        }
    }
}

fn main() {
    drop_stale_permissions();
    // The proof capability sits in its own folder and is read only when the
    // shell-proof feature is on, so a normal build never sees it.
    #[cfg(feature = "shell-proof")]
    let pattern = "./capabilities*/*.json";
    #[cfg(not(feature = "shell-proof"))]
    let pattern = "./capabilities/*.json";
    println!("cargo:rerun-if-changed=capabilities");
    println!("cargo:rerun-if-changed=capabilities-proof");
    tauri_build::try_build(
        Attributes::new()
            .app_manifest(AppManifest::new().commands(COMMANDS))
            .capabilities_path_pattern(pattern),
    )
    .expect("failed to run tauri-build");
}
